export { CheckProfanityResult, FilterConfig, Language } from 'glin-profanity';

/**
 * OpenClaw Plugin - TypeScript Tools Registration
 *
 * This module provides TypeScript-based tools that can be registered
 * with OpenClaw's plugin system for advanced integrations.
 *
 * @example
 * ```typescript
 * // In your OpenClaw plugin
 * import { registerProfanityTools } from 'openclaw-profanity/plugin';
 *
 * export default function(api) {
 *   registerProfanityTools(api);
 * }
 * ```
 *
 * @remarks
 * Works with OpenClaw, Moltbot (legacy), and Clawdbot (legacy).
 *
 * @packageDocumentation
 */

/**
 * OpenClaw API interface (minimal type for plugin registration)
 */
interface OpenClawAPI {
    registerTool: (tool: OpenClawTool) => void;
}
/**
 * OpenClaw tool definition
 */
interface OpenClawTool {
    name: string;
    description: string;
    parameters: unknown;
    execute: (id: string, params: Record<string, unknown>) => Promise<ToolResult>;
}
/**
 * Tool execution result
 */
interface ToolResult {
    content: Array<{
        type: 'text';
        text: string;
    }>;
    isError?: boolean;
}
/**
 * Check profanity tool definition
 */
declare const checkProfanityTool: OpenClawTool;
/**
 * Censor text tool definition
 */
declare const censorTextTool: OpenClawTool;
/**
 * Batch check tool definition
 */
declare const batchCheckTool: OpenClawTool;
/**
 * Analyze context tool definition
 */
declare const analyzeContextTool: OpenClawTool;
/**
 * Get supported languages tool
 */
declare const getSupportedLanguagesTool: OpenClawTool;
/**
 * All available profanity tools
 */
declare const profanityTools: {
    checkProfanity: OpenClawTool;
    censorText: OpenClawTool;
    batchCheck: OpenClawTool;
    analyzeContext: OpenClawTool;
    getSupportedLanguages: OpenClawTool;
};
/**
 * Register all profanity tools with OpenClaw API
 *
 * @example
 * ```typescript
 * // In your OpenClaw plugin entry
 * export default function(api) {
 *   registerProfanityTools(api);
 * }
 * ```
 */
declare function registerProfanityTools(api: OpenClawAPI): void;
/**
 * Default export for OpenClaw plugin discovery
 *
 * @remarks
 * OpenClaw (and legacy Moltbot/Clawdbot) will automatically
 * call this function when loading the plugin.
 */
declare function openclawPlugin(api: OpenClawAPI): void;

export { type OpenClawAPI, type OpenClawTool, type ToolResult, analyzeContextTool, batchCheckTool, censorTextTool, checkProfanityTool, openclawPlugin as default, getSupportedLanguagesTool, profanityTools, registerProfanityTools };
